    <script>
        // Three.js Runtime Simulation (Embedded)
        // Note: In a real implementation, this would be loaded from ../runtime/three-runtime.js
        // For this standalone version, we'll simulate the required globals
        window.THREE = {
            Scene: function() { this.children = []; this.add = function(obj) { this.children.push(obj); }; },
            PerspectiveCamera: function() { this.position = { set: function() {} }; },
            WebGLRenderer: function() { this.setSize = function() {}; this.render = function() {}; },
            AmbientLight: function() {},
            DirectionalLight: function() {},
            BoxGeometry: function() {},
            Mesh: function() { this.position = { set: function() {} }; },
            MeshBasicMaterial: function() {},
            Color: function() { this.set = function() {}; },
            Vector3: function() { this.set = function() {}; },
            OrbitControls: function() { this.update = function() {}; },
            BufferGeometry: function() {},
            BufferAttribute: function() {},
            Line: function() {},
            LineBasicMaterial: function() {},
            PlaneGeometry: function() {},
            Group: function() { this.add = function() {}; },
            TextureLoader: function() { this.load = function() { return { image: { width: 0, height: 0 } }; }; },
            DoubleSide: 0,
            AdditiveBlending: 2,
            LinearFilter: 1000,
            RepeatWrapping: 10000,
            RGBAFormat: 2082
        };

        // Main Application
        document.addEventListener('DOMContentLoaded', function() {
            // Check for mobile devices
            const isMobile = /Mobi|Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
            if (isMobile) {
                document.getElementById('mobile-warning').style.display = 'block';
            }

            // Initialize Three.js environment
            const container = document.getElementById('three-container');
            const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
            renderer.setPixelRatio(window.devicePixelRatio);
            renderer.setSize(container.clientWidth, container.clientHeight);
            container.appendChild(renderer.domElement);

            // Scene setup
            const scene = new THREE.Scene();
            scene.background = new THREE.Color(0x1a1a2e);

            // Camera
            const camera = new THREE.PerspectiveCamera(60, container.clientWidth / container.clientHeight, 0.1, 10000);
            camera.position.set(0, 0, 500);

            // Lights
            const ambientLight = new THREE.AmbientLight(0x404040);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(1, 1, 1);
            scene.add(directionalLight);

            // Controls
            const controls = new THREE.OrbitControls(camera, renderer.domElement);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.screenSpacePanning = false;
            controls.minDistance = 100;
            controls.maxDistance = 1000;
            controls.maxPolarAngle = Math.PI * 0.9;

            // UI Controls
            const designPhaseSelect = document.getElementById('design-phase');
            const viewTypeSelect = document.getElementById('view-type');
            const floorLevelSelect = document.getElementById('floor-level');
            const resetViewBtn = document.getElementById('reset-view');
            const toggleInfoBtn = document.getElementById('toggle-info');
            const toggleReferenceBtn = document.getElementById('toggle-reference');
            const closeMobileWarningBtn = document.getElementById('close-mobile-warning');
            const referencePanel = document.getElementById('reference-panel');
            const designInfoPanel = document.getElementById('design-info');
            const currentDimensions = document.getElementById('current-dimensions');

            // Model data
            let currentModel = null;
            let currentViewType = '3d';
            let currentFloorLevel = 10;

            // Generate building geometry
            function generateBuildingGeometry(phase) {
                const group = new THREE.Group();

                // Base parameters
                const totalHeight = 555;
                const baseWidth = 100;
                const baseDepth = 100;
                const topWidth = 40;
                const topDepth = 40;
                const floorHeight = totalHeight / 123;

                // Phase-specific adjustments
                let width, depth, coreSize, exteriorDetail;
                switch(phase) {
                    case 'concept':
                        width = baseWidth * 0.8;
                        depth = baseDepth * 0.8;
                        coreSize = 20;
                        exteriorDetail = 0.1;
                        break;
                    case 'initial':
                        width = baseWidth * 0.9;
                        depth = baseDepth * 0.9;
                        coreSize = 25;
                        exteriorDetail = 0.2;
                        break;
                    case 'foundation':
                        width = baseWidth;
                        depth = baseDepth;
                        coreSize = 30;
                        exteriorDetail = 0.3;
                        break;
                    case 'core':
                        width = baseWidth * 0.95;
                        depth = baseDepth * 0.95;
                        coreSize = 35;
                        exteriorDetail = 0.5;
                        break;
                    case 'final':
                    default:
                        width = baseWidth;
                        depth = baseDepth;
                        coreSize = 40;
                        exteriorDetail = 1.0;
                        break;
                }

                // Create foundation
                const foundationHeight = 30;
                const foundationGeometry = new THREE.BoxGeometry(width, foundationHeight, depth);
                const foundationMaterial = new THREE.MeshBasicMaterial({
                    color: 0x3a3a3a,
                    transparent: true,
                    opacity: 0.7
                });
                const foundation = new THREE.Mesh(foundationGeometry, foundationMaterial);
                foundation.position.y = -foundationHeight/2;
                group.add(foundation);

                // Create floors
                for (let i = 0; i < 123; i++) {
                    const floorY = -foundationHeight + (i * floorHeight);
                    const floorWidth = width * (1 - (i/123) * (1 - (topWidth/width)));
                    const floorDepth = depth * (1 - (i/123) * (1 - (topDepth/depth)));

                    // Floor slab
                    const slabGeometry = new THREE.BoxGeometry(floorWidth, floorHeight * 0.1, floorDepth);
                    const slabMaterial = new THREE.MeshBasicMaterial({
                        color: 0x5a5a5a,
                        transparent: true,
                        opacity: 0.5
                    });
                    const slab = new THREE.Mesh(slabGeometry, slabMaterial);
                    slab.position.y = floorY + (floorHeight * 0.05);
                    group.add(slab);

                    // Exterior walls (with phase-specific detail)
                    const wallThickness = 5;
                    const wallHeight = floorHeight * 0.9;

                    // Front and back walls
                    const frontWallGeometry = new THREE.BoxGeometry(floorWidth, wallHeight, wallThickness);
                    const frontWallMaterial = new THREE.MeshBasicMaterial({
                        color: 0x2a2a2a,
                        transparent: true,
                        opacity: 0.8
                    });
                    const frontWall = new THREE.Mesh(frontWallGeometry, frontWallMaterial);
                    frontWall.position.set(0, floorY + (wallHeight/2), floorDepth/2 + wallThickness/2);
                    group.add(frontWall);

                    const backWallGeometry = new THREE.BoxGeometry(floorWidth, wallHeight, wallThickness);
                    const backWall = new THREE.Mesh(backWallGeometry, frontWallMaterial);
                    backWall.position.set(0, floorY + (wallHeight/2), -floorDepth/2 - wallThickness/2);
                    group.add(backWall);

                    // Side walls
                    const sideWallGeometry = new THREE.BoxGeometry(wallThickness, wallHeight, floorDepth);
                    const sideWallMaterial = new THREE.MeshBasicMaterial({
                        color: 0x2a2a2a,
                        transparent: true,
                        opacity: 0.8
                    });
                    const leftWall = new THREE.Mesh(sideWallGeometry, sideWallMaterial);
                    leftWall.position.set(-floorWidth/2 - wallThickness/2, floorY + (wallHeight/2), 0);
                    group.add(leftWall);

                    const rightWall = new THREE.Mesh(sideWallGeometry, sideWallMaterial);
                    rightWall.position.set(floorWidth/2 + wallThickness/2, floorY + (wallHeight/2), 0);
                    group.add(rightWall);

                    // Add phase-specific exterior details
                    if (phase !== 'concept') {
                        // Ceramic line details (simplified)
                        const lineMaterial = new THREE.LineBasicMaterial({
                            color: 0xffffff,
                            linewidth: 1,
                            transparent: true,
                            opacity: 0.3
                        });

                        // Vertical lines
                        const verticalLines = [];
                        const verticalSegments = Math.max(2, Math.floor(floorWidth / 10));
                        for (let j = 0; j <= verticalSegments; j++) {
                            const x = (j / verticalSegments) * floorWidth - floorWidth/2;
                            const points = [];
                            points.push(new THREE.Vector3(x, floorY, floorDepth/2));
                            points.push(new THREE.Vector3(x, floorY + wallHeight, floorDepth/2));
                            verticalLines.push(points);

                            points = [];
                            points.push(new THREE.Vector3(x, floorY, -floorDepth/2));
                            points.push(new THREE.Vector3(x, floorY + wallHeight, -floorDepth/2));
                            verticalLines.push(points);
                        }

                        // Horizontal lines
                        const horizontalLines = [];
                        const horizontalSegments = Math.max(2, Math.floor(floorDepth / 10));
                        for (let j = 0; j <= horizontalSegments; j++) {
                            const z = (j / horizontalSegments) * floorDepth - floorDepth/2;
                            const points = [];
                            points.push(new THREE.Vector3(floorWidth/2, floorY, z));
                            points.push(new THREE.Vector3(floorWidth/2, floorY + wallHeight, z));
                            horizontalLines.push(points);

                            points = [];
                            points.push(new THREE.Vector3(-floorWidth/2, floorY, z));
                            points.push(new THREE.Vector3(-floorWidth/2, floorY + wallHeight, z));
                            horizontalLines.push(points);
                        }

                        // Create line geometry
                        const lineGeometry = new THREE.BufferGeometry();
                        const pointsArray = [];

                        verticalLines.forEach(line => {
                            line.forEach(point => pointsArray.push(point.x, point.y, point.z));
                        });

                        horizontalLines.forEach(line => {
                            line.forEach(point => pointsArray.push(point.x, point.y, point.z));
                        });

                        lineGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pointsArray), 3));
                        const lines = new THREE.Line(lineGeometry, lineMaterial);
                        group.add(lines);
                    }

                    // Core structure (simplified)
                    if (phase !== 'concept' && phase !== 'initial') {
                        const coreGeometry = new THREE.BoxGeometry(coreSize, floorHeight * 0.9, coreSize);
                        const coreMaterial = new THREE.MeshBasicMaterial({
                            color: 0x1a1a1a,
                            transparent: true,
                            opacity: 0.9
                        });
                        const core = new THREE.Mesh(coreGeometry, coreMaterial);
                        core.position.y = floorY + (floorHeight * 0.45);
                        group.add(core);
                    }
                }

                // Add phase-specific elements
                switch(phase) {
                    case 'concept':
                        // Add ceramic line concept visualization
                        const conceptLines = createCeramicLines(width, depth, totalHeight);
                        group.add(conceptLines);
                        break;
                    case 'final':
                        // Add spire
                        const spireHeight = 50;
                        const spireGeometry = new THREE.ConeGeometry(15, spireHeight, 8);
                        const spireMaterial = new THREE.MeshBasicMaterial({
                            color: 0x3a3a3a,
                            transparent: true,
                            opacity: 0.7
                        });
                        const spire = new THREE.Mesh(spireGeometry, spireMaterial);
                        spire.position.y = totalHeight - (spireHeight/2);
                        spire.rotation.x = Math.PI/2;
                        group.add(spire);
                        break;
                }

                return group;
            }

            function createCeramicLines(width, depth, height) {
                const group = new THREE.Group();
                const lineMaterial = new THREE.LineBasicMaterial({
                    color: 0xffffff,
                    linewidth: 1,
                    transparent: true,
                    opacity: 0.5,
                    blending: THREE.AdditiveBlending
                });

                // Create organic ceramic line patterns
                const segments = 20;
                const points = [];

                // Vertical organic lines
                for (let i = 0; i < segments; i++) {
                    const x = (Math.random() - 0.5) * width * 0.8;
                    const z = (Math.random() - 0.5) * depth * 0.8;
                    const yStart = -30 + Math.random() * 20;
                    const yEnd = height + Math.random() * 50;

                    points.push(new THREE.Vector3(x, yStart, z));
                    points.push(new THREE.Vector3(x, yEnd, z));
                }

                // Horizontal organic lines
                for (let i = 0; i < segments; i++) {
                    const x = (Math.random() - 0.5) * width * 0.8;
                    const z = (Math.random() - 0.5) * depth * 0.8;
                    const y = -30 + Math.random() * height;
                    const xStart = (Math.random() - 0.5) * width * 0.6;
                    const xEnd = (Math.random() - 0.5) * width * 0.6;

                    points.push(new THREE.Vector3(xStart, y, z));
                    points.push(new THREE.Vector3(xEnd, y, z));
                }

                // Create line geometry
                const lineGeometry = new THREE.BufferGeometry();
                const positions = [];

                points.forEach(point => {
                    positions.push(point.x, point.y, point.z);
                });

                lineGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
                const lines = new THREE.Line(lineGeometry, lineMaterial);
                group.add(lines);

                return group;
            }

            function generateFloorPlan(floorLevel) {
                const group = new THREE.Group();
                const floorHeight = 555 / 123;
                const yPosition = -30 + (floorLevel * floorHeight);

                // Base parameters
                const baseWidth = 100;
                const baseDepth = 100;
                const topWidth = 40;
                const topDepth = 40;

                // Calculate floor dimensions
                const floorWidth = baseWidth * (1 - ((floorLevel-1)/122) * (1 - (topWidth/baseWidth)));
                const floorDepth = baseDepth * (1 - ((floorLevel-1)/122) * (1 - (topDepth/baseDepth)));

                // Floor outline
                const outlineMaterial = new THREE.LineBasicMaterial({
                    color: 0xffffff,
                    linewidth: 2
                });

                const outlinePoints = [
                    new THREE.Vector3(-floorWidth/2, yPosition, floorDepth/2),
                    new THREE.Vector3(floorWidth/2, yPosition, floorDepth/2),
                    new THREE.Vector3(floorWidth/2, yPosition, -floorDepth/2),
                    new THREE.Vector3(-floorWidth/2, yPosition, -floorDepth/2),
                    new THREE.Vector3(-floorWidth/2, yPosition, floorDepth/2)
                ];

                const outlineGeometry = new THREE.BufferGeometry();
                const outlinePositions = [];

                outlinePoints.forEach(point => {
                    outlinePositions.push(point.x, point.y, point.z);
                });

                outlineGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(outlinePositions), 3));
                const outline = new THREE.Line(outlineGeometry, outlineMaterial);
                group.add(outline);

                // Core position
                const coreSize = 40;
                const coreOutlinePoints = [
                    new THREE.Vector3(-coreSize/2, yPosition, coreSize/2),
                    new THREE.Vector3(coreSize/2, yPosition, coreSize/2),
                    new THREE.Vector3(coreSize/2, yPosition, -coreSize/2),
                    new THREE.Vector3(-coreSize/2, yPosition, -coreSize/2),
                    new THREE.Vector3(-coreSize/2, yPosition, coreSize/2)
                ];

                const coreOutlineGeometry = new THREE.BufferGeometry();
                const coreOutlinePositions = [];

                coreOutlinePoints.forEach(point => {
                    coreOutlinePositions.push(point.x, point.y, point.z);
                });

                coreOutlineGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(coreOutlinePositions), 3));
                const coreOutline = new THREE.Line(coreOutlineGeometry, new THREE.LineBasicMaterial({
                    color: 0xff9f43,
                    linewidth: 1
                }));
                group.add(coreOutline);

                // Add floor number label
                const canvas = document.createElement('canvas');
                canvas.width = 256;
                canvas.height = 64;
                const context = canvas.getContext('2d');
                context.fillStyle = 'rgba(255,255,255,0.8)';
                context.font = 'bold 24px Arial';
                context.textAlign = 'center';
                context.textBaseline = 'middle';
                context.fillText(`지상 ${floorLevel}층`, canvas.width/2, canvas.height/2);

                const texture = new THREE.Texture(canvas);
                texture.needsUpdate = true;

                const labelMaterial = new THREE.SpriteMaterial({ map: texture });
                const label = new THREE.Sprite(labelMaterial);
                label.position.set(0, yPosition + 5, 0);
                label.scale.set(20, 10, 1);
                group.add(label);

                return group;
            }

            function generateElevationView() {
                const group = new THREE.Group();

                // Base parameters
                const totalHeight = 555;
                const baseWidth = 100;
                const baseDepth = 100;
                const topWidth = 40;
                const topDepth = 40;

                // Create side profile
                const profileMaterial = new THREE.LineBasicMaterial({
                    color: 0xffffff,
                    linewidth: 1
                });

                const profilePoints = [];
                for (let i = 0; i <= 123; i++) {
                    const y = -30 + (i * (totalHeight / 123));
                    const width = baseWidth * (1 - (i/123) * (1 - (topWidth/baseWidth)));

                    profilePoints.push(new THREE.Vector3(-width/2, y, 0));
                    profilePoints.push(new THREE.Vector3(width/2, y, 0));
                }

                const profileGeometry = new THREE.BufferGeometry();
                const profilePositions = [];

                profilePoints.forEach(point => {
                    profilePositions.push(point.x, point.y, point.z);
                });

                profileGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(profilePositions), 3));
                const profile = new THREE.Line(profileGeometry, profileMaterial);
                group.add(profile);

                // Add floor markers
                for (let i = 0; i <= 123; i += 10) {
                    const y = -30 + (i * (totalHeight / 123));
                    const canvas = document.createElement('canvas');
                    canvas.width = 64;
                    canvas.height = 32;
                    const context = canvas.getContext('2d');
                    context.fillStyle = 'rgba(255,255,255,0.7)';
                    context.font = 'bold 16px Arial';
                    context.textAlign = 'center';
                    context.textBaseline = 'middle';
                    context.fillText(`${i}층`, canvas.width/2, canvas.height/2);

                    const texture = new THREE.Texture(canvas);
                    texture.needsUpdate = true;

                    const labelMaterial = new THREE.SpriteMaterial({ map: texture });
                    const label = new THREE.Sprite(labelMaterial);
                    label.position.set(0, y, 0);
                    label.scale.set(8, 4, 1);
                    group.add(label);
                }

                // Add height markers
                const heightMarkers = [
                    { y: -30, text: '기초' },
                    { y: totalHeight, text: '555m' }
                ];

                heightMarkers.forEach(marker => {
                    const canvas = document.createElement('canvas');
                    canvas.width = 128;
                    canvas.height = 32;
                    const context = canvas.getContext('2d');
                    context.fillStyle = 'rgba(255,255,255,0.7)';
                    context.font = 'bold 16px Arial';
                    context.textAlign = 'center';
                    context.textBaseline = 'middle';
                    context.fillText(marker.text, canvas.width/2, canvas.height/2);

                    const texture = new THREE.Texture(canvas);
                    texture.needsUpdate = true;

                    const labelMaterial = new THREE.SpriteMaterial({ map: texture });
                    const label = new THREE.Sprite(labelMaterial);
                    label.position.set(0, marker.y, 0);
                    label.scale.set(12, 6, 1);
                    group.add(label);
                });

                return group;
            }

            function generateSectionView() {
                const group = new THREE.Group();

                // Base parameters
                const totalHeight = 555;
                const baseWidth = 100;
                const baseDepth = 100;
                const topWidth = 40;
                const topDepth = 40;

                // Create cross section
                const sectionMaterial = new THREE.LineBasicMaterial({
                    color: 0xffffff,
                    linewidth: 1
                });

                // Front section
                const frontPoints = [];
                for (let i = 0; i <= 123; i++) {
                    const y = -30 + (i * (totalHeight / 123));
                    const depth = baseDepth * (1 - (i/123) * (1 - (topDepth/baseDepth)));

                    frontPoints.push(new THREE.Vector3(-baseWidth/2, y, depth/2));
                    frontPoints.push(new THREE.Vector3(baseWidth/2, y, depth/2));
                }

                const frontGeometry = new THREE.BufferGeometry();
                const frontPositions = [];

                frontPoints.forEach(point => {
                    frontPositions.push(point.x, point.y, point.z);
                });

                frontGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(frontPositions), 3));
                const frontSection = new THREE.Line(frontGeometry, sectionMaterial);
                group.add(frontSection);

                // Back section
                const backPoints = [];
                for (let i = 0; i <= 123; i++) {
                    const y = -30 + (i * (totalHeight / 123));
                    const depth = baseDepth * (1 - (i/123) * (1 - (topDepth/baseDepth)));

                    backPoints.push(new THREE.Vector3(-baseWidth/2, y, -depth/2));
                    backPoints.push(new THREE.Vector3(baseWidth/2, y, -depth/2));
                }

                const backGeometry = new THREE.BufferGeometry();
                const backPositions = [];

                backPoints.forEach(point => {
                    backPositions.push(point.x, point.y, point.z);
                });

                backGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(backPositions), 3));
                const backSection = new THREE.Line(backGeometry, sectionMaterial);
                group.add(backSection);

                // Add core section
                const coreSize = 40;
                const corePoints = [
                    new THREE.Vector3(-coreSize/2, -30, coreSize/2),
                    new THREE.Vector3(coreSize/2, -30, coreSize/2),
                    new THREE.Vector3(coreSize/2, totalHeight, coreSize/2),
                    new THREE.Vector3(-coreSize/2, totalHeight, coreSize/2),
                    new THREE.Vector3(-coreSize/2, -30, coreSize/2)
                ];

                const coreGeometry = new THREE.BufferGeometry();
                const corePositions = [];

                corePoints.forEach(point => {
                    corePositions.push(point.x, point.y, point.z);
                });

                coreGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(corePositions), 3));
                const coreSection = new THREE.Line(coreGeometry, new THREE.LineBasicMaterial({
                    color: 0xff9f43,
                    linewidth: 1
                }));
                group.add(coreSection);

                return group;
            }

            function generateSitePlan() {
                const group = new THREE.Group();

                // Base parameters
                const totalHeight = 555;
                const baseWidth = 100;
                const baseDepth = 100;

                // Building footprint
                const footprintMaterial = new THREE.LineBasicMaterial({
                    color: 0xffffff,
                    linewidth: 2
                });

                const footprintPoints = [
                    new THREE.Vector3(-baseWidth/2, -30, baseDepth/2),
                    new THREE.Vector3(baseWidth/2, -30, baseDepth/2),
                    new THREE.Vector3(baseWidth/2, -30, -baseDepth/2),
                    new THREE.Vector3(-baseWidth/2, -30, -baseDepth/2),
                    new THREE.Vector3(-baseWidth/2, -30, baseDepth/2)
                ];

                const footprintGeometry = new THREE.BufferGeometry();
                const footprintPositions = [];

                footprintPoints.forEach(point => {
                    footprintPositions.push(point.x, point.y, point.z);
                });

                footprintGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(footprintPositions), 3));
                const footprint = new THREE.Line(footprintGeometry, footprintMaterial);
                group.add(footprint);

                // Add height indicator
                const heightIndicator = new THREE.ArrowHelper(
                    new THREE.Vector3(0, 1, 0),
                    new THREE.Vector3(0, 0, 0),
                    totalHeight,
                    0xffffff,
                    10,
                    5
                );
                group.add(heightIndicator);

                // Add labels
                const canvas = document.createElement('canvas');
                canvas.width = 256;
                canvas.height = 64;
                const context = canvas.getContext('2d');
                context.fillStyle = 'rgba(255,255,255,0.8)';
                context.font = 'bold 24px Arial';
                context.textAlign = 'center';
                context.textBaseline = 'middle';
                context.fillText('롯데월드타워', canvas.width/2, canvas.height/2);

                const texture = new THREE.Texture(canvas);
                texture.needsUpdate = true;

                const labelMaterial = new THREE.SpriteMaterial({ map: texture });
                const label = new THREE.Sprite(labelMaterial);
                label.position.set(0, -30, 0);
                label.scale.set(30, 15, 1);
