                return group;
            }

            // Update current model based on selections
            function updateModel() {
                const phase = designPhaseSelect.value;
                const viewType = viewTypeSelect.value;
                const floorLevel = parseInt(floorLevelSelect.value);

                // Clear existing model
                while(scene.children.length > 0) {
                    scene.remove(scene.children[0]);
                }

                // Add grid helper
                const gridHelper = new THREE.GridHelper(200, 20);
                scene.add(gridHelper);

                // Add axes helper
                const axesHelper = new THREE.AxesHelper(50);
                scene.add(axesHelper);

                // Generate appropriate model based on view type
                let model;
                switch(viewType) {
                    case '3d':
                        model = generateBuildingGeometry(phase);
                        break;
                    case 'floorplan':
                        model = generateFloorPlan(floorLevel);
                        currentFloorLevel = floorLevel;
                        break;
                    case 'elevation':
                        model = generateElevationView();
                        break;
                    case 'section':
                        model = generateSectionView();
                        break;
                    case 'siteplan':
                        model = generateSitePlan();
                        break;
                }

                scene.add(model);
                currentModel = model;

                // Update dimensions display
                if (viewType === '3d') {
                    const totalHeight = 555;
                    const baseWidth = 100;
                    const baseDepth = 100;
                    const topWidth = 40;
                    const topDepth = 40;

                    let width, depth;
                    switch(phase) {
                        case 'concept':
                            width = baseWidth * 0.8;
                            depth = baseDepth * 0.8;
                            break;
                        case 'initial':
                            width = baseWidth * 0.9;
                            depth = baseDepth * 0.9;
                            break;
                        case 'foundation':
                            width = baseWidth;
                            depth = baseDepth;
                            break;
                        case 'core':
                            width = baseWidth * 0.95;
                            depth = baseDepth * 0.95;
                            break;
                        case 'final':
                        default:
                            width = baseWidth;
                            depth = baseDepth;
                            break;
                    }

                    currentDimensions.innerHTML = `
                        <div>• 전체 높이: ${totalHeight.toFixed(0)}m</div>
                        <div>• 기준층 면적: ${(width * depth).toFixed(0)}m²</div>
                        <div>• 최상층 면적: ${(topWidth * topDepth).toFixed(0)}m²</div>
                        <div>• 현재 단계: ${phase.replace(/([A-Z])/g, ' $1').toUpperCase()}</div>
                    `;
                } else if (viewType === 'floorplan') {
                    const floorHeight = 555 / 123;
                    const yPosition = -30 + (floorLevel * floorHeight);

                    const baseWidth = 100;
                    const baseDepth = 100;
                    const topWidth = 40;
                    const topDepth = 40;

                    const floorWidth = baseWidth * (1 - ((floorLevel-1)/122) * (1 - (topWidth/baseWidth)));
                    const floorDepth = baseDepth * (1 - ((floorLevel-1)/122) * (1 - (topDepth/baseDepth)));

                    currentDimensions.innerHTML = `
                        <div>• 층수: 지상 ${floorLevel}층</div>
                        <div>• 층 높이: ${floorHeight.toFixed(1)}m</div>
                        <div>• 층 면적: ${(floorWidth * floorDepth).toFixed(0)}m²</div>
                        <div>• 현재 단계: ${phase.replace(/([A-Z])/g, ' $1').toUpperCase()}</div>
                    `;
                } else {
                    currentDimensions.innerHTML = '--';
                }

                // Reset camera based on view type
                resetCamera(viewType);
            }

            function resetCamera(viewType) {
                if (viewType === '3d') {
                    camera.position.set(0, 0, 500);
                    camera.lookAt(0, 0, 0);
                    controls.reset();
                } else if (viewType === 'floorplan') {
                    camera.position.set(0, 200, 200);
                    camera.lookAt(0, -30, 0);
                    controls.reset();
                } else if (viewType === 'elevation') {
                    camera.position.set(300, 0, 0);
                    camera.lookAt(0, 0, 0);
                    controls.reset();
                } else if (viewType === 'section') {
                    camera.position.set(0, 0, 300);
                    camera.lookAt(0, 0, 0);
                    controls.reset();
                } else if (viewType === 'siteplan') {
                    camera.position.set(0, 300, 300);
                    camera.lookAt(0, -30, 0);
                    controls.reset();
                }
            }

            // Event listeners
            designPhaseSelect.addEventListener('change', updateModel);
            viewTypeSelect.addEventListener('change', updateModel);
            floorLevelSelect.addEventListener('change', updateModel);
            resetViewBtn.addEventListener('click', () => {
                resetCamera(viewTypeSelect.value);
            });
            toggleInfoBtn.addEventListener('click', () => {
                designInfoPanel.classList.toggle('hidden');
            });
            toggleReferenceBtn.addEventListener('click', () => {
                referencePanel.classList.toggle('hidden');
            });
            closeMobileWarningBtn.addEventListener('click', () => {
                document.getElementById('mobile-warning').style.display = 'none';
            });

            // Initial model load
            setTimeout(() => {
                document.querySelector('.loading').style.display = 'none';
                updateModel();
            }, 500);

            // Handle window resize
            window.addEventListener('resize', () => {
                camera.aspect = container.clientWidth / container.clientHeight;
                camera.updateProjectionMatrix();
                renderer.setSize(container.clientWidth, container.clientHeight);
            });

            // Animation loop
            function animate() {
                requestAnimationFrame(animate);
                controls.update();
                renderer.render(scene, camera);
            }
            animate();
        });
    </script>
